  AND user_id = #{userId}

mapper.update:
UPDATE t_ai_proactive_subscription
SET status = #{status},
    edit_time = CURRENT_TIMESTAMP,
    edit_by = #{editBy}
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE t_ai_proactive_subscription
SET last_triggered_time = #{lastTriggeredTime},
    next_trigger_time = #{nextTriggerTime},
    edit_time = CURRENT_TIMESTAMP,
    edit_by = #{editBy}
WHERE id = #{id}
